@@ -74,6 +74,7 @@ static const value_string ltype_vals[] = {
 	{ LINUX_SLL_P_IRDA_LAP,	"IrDA LAP" },
 	{ LINUX_SLL_P_ISI,	"ISI" },
 	{ LINUX_SLL_P_IEEE802154,	"IEEE 802.15.4" },
+	{ LINUX_SLL_P_MCTP,	"MCTP" },
 	{ 0,			NULL }
 };

@@ -47,6 +47,7 @@ typedef enum {
     AT_AX25,               /* AX.25 */
     AT_VINES,              /* Banyan Vines address */
